function LastWeekRange(qid,q) 
{
  //var today = new Date();
var today = new Date(f(qid).get());

  // Find last Saturday
  var day = today.getDay(); // 0=Sunday, 6=Saturday
  var diff = (day === 0 ? 0 : day); // how many days since last Sunday
  var lastSunday = new Date(today);
  lastSunday.setDate(today.getDate() - diff);

  // Previous Monday = Sunday - 6 days
  var lastMonday = new Date(lastSunday);
  lastMonday.setDate(lastSunday.getDate() - 6);

  // Format as DD/MM/YYYY
  function formatDate(d) {
    var dd = String(d.getDate()).padStart(2, '0');
    var mm = String(d.getMonth() + 1).padStart(2, '0');
    var yyyy = d.getFullYear();
    return dd + "/" + mm + "/" + yyyy;
  }

  f(q + "_mon").set(formatDate(lastMonday));   // Monday
  f(q + "_sun").set(formatDate(lastSunday));   // Sunday

};

LastWeekRange("weekdate", "week");


