// validate and return a postcode from pcode_list
function getFinalPostcode4(postcodeInput) {
    var postcode = String(postcodeInput).padStart(4, '0');
    var postcodeList = f('pcode_list3').get().split(',');
    return postcodeList.includes(postcode) ? postcode : "Invalid postcode";
}

