    Confirmit.page.getQuestion(qId).setValue(val);
  }


function sumdisplayTotal(obj)
{
  var sumtotal=''

  $('.cf-list',obj).eq(0).before("<div class='sum_total_container'>Annual income: $<span class='sum_total'></span> " +sumtotal+ "</div>");
    if ($('.sum_total_container',obj).length > 1){
        $(".sum_total_container",obj).eq(1).remove()
    }
    $('.cf-radio-answer__other.cf-text-box',obj).on("keyup focus input blur",function(e) {
           	$(this).val($(this).val().split('').filter(char => char >= '0' && char <= '9').join(''));

            sumValues(obj);
        })

}

 function sumValues(obj) {
        var USLHRSM_new = "^f('USLHRSM').item('1').get()^"; 
   if (isNaN(USLHRSM_new)) {
         USLHRSM_new = 0;
        }  
  var code1onPage = $("#SALARYC_1_other").length>0
  var indexajust=0
  var val1=0
        var total2 = 0
        var totalNum=0

        if (code1onPage){
               val1 = ($('.cf-radio-answer__other.cf-text-box', obj).eq(0).val()*USLHRSM_new* 365.25) / 7
         }
        else
        {
          val1=0
          indexajust=1
        }
        var val2 = ($('.cf-radio-answer__other.cf-text-box', obj).eq(1 - indexajust).val()* 5 * 365.25) / 7
        var val3 = ($('.cf-radio-answer__other.cf-text-box', obj).eq(2 - indexajust).val()* 365.25) / 7
        var val4 = ($('.cf-radio-answer__other.cf-text-box', obj).eq(3 - indexajust).val()* 365.25) / 14
        var val5 = $('.cf-radio-answer__other.cf-text-box', obj).eq(4 - indexajust).val()* 12
        var val6 = $('.cf-radio-answer__other.cf-text-box', obj).eq(5 - indexajust).val()


        total2 = thousands_separators(parseFloat(val1 + val2 + val3 + val4 + val5 + val6).toFixed(0))
        totalNum= parseFloat(val1 + val2 + val3 + val4 + val5 + val6).toFixed(0)
 /*
        if (isNaN(total2)) {
         total2 = 0;
        }    */    
        $('.sum_total', obj).text(total2);

        setQuestionValue("SALARYCx2", Math.round(totalNum));

 }
    function thousands_separators(num)
  {
    var num_parts = num.toString().split(".");
    num_parts[0] = num_parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return num_parts.join(".");
  }

