var val1 = 0, val2 = 0, val3 = 0, val4 = 0, val5 = 0, val6 = 0, val7 = 0, val8 = 0;
var val1C = 0, val2C = 0, val3C = 0, val4C = 0, val5C = 0, val6C = 0, val7C = 0, val8C = 0;

if (f('MORE1JOB').any('1')) {
    if (!f('SALARYB').toBoolean()) {
        if (f('SALARYA').any('1')){
            val1 = 0+((f('SALARYA_1_other').get()*USLHRS_new* 365.25) / 7)
        }
        else if (f('SALARYA').any('2')){
            val2 = 0+((f('SALARYA_2_other').get()* 5 * 365.25) / 7)
        }
        else if (f('SALARYA').any('3')){
            val3 = 0+((f('SALARYA_3_other').get()* 365.25) / 7)
        }
        else if (f('SALARYA').any('4')){
            val4 = 0+((f('SALARYA_4_other').get()* 365.25) / 14)
        }
        else if (f('SALARYA').any('5')){
            val5 = 0+(f('SALARYA_5_other').get()* 12)
        }
        else 
        if (f('SALARYA').any('6')){
            val6 = 0+(f('SALARYA_6_other').get()*1)
        }
        else if (f('SALARYA').any('7')) {
            var val7 = 0
        }else if (f('SALARYA').any('8')) {
            var val8 = -1
        }
    }
    var totalNum = 0

    totalNum= parseFloat(val1 + val2 + val3 + val4 + val5 + val6 + val7 + val8)
    f('AllIncome').set(totalNum);

    if (!f('SALARYB').any('12') && f('SALARYB').toBoolean()){
        f('SALARYB_SCORE').set(f('SALARYB'))
        f('AllIncome').set(f('SALARYB_SCORE').valueLabel())
    }
    if (!f('SALARYD').toBoolean()) {
        if (f('SALARYC').any('1')){
            val1C = 0+((f('SALARYC_1_other').get()*USLHRSM_new* 365.25) / 7)
        }
        else if (f('SALARYC').any('2')){
            val2C = 0+((f('SALARYC_2_other').get()* 5 * 365.25) / 7)
        }
        else if (f('SALARYC').any('3')){
            val3C = 0+((f('SALARYC_3_other').get()* 365.25) / 7)
        }
        else if (f('SALARYC').any('4')){
            val4C = 0+((f('SALARYC_4_other').get()* 365.25) / 14)
        }
        else if (f('SALARYC').any('5')){
            val5C = 0+(f('SALARYC_5_other').get()* 12)
        }
        else if (f('SALARYC').any('6')){
            val6C = 0+(f('SALARYC_6_other').get()*1)
        }
        else if (f('SALARYC').any('7')) {
            var val7C = 0
        }else if (f('SALARYC').any('8')) {
            var val8C = -1
        }
    }
    var totalNumC = 0

    totalNumC = parseFloat(val1C + val2C + val3C + val4C + val5C + val6C + val7C + val8C)
    //totalNum = val1 + val2 + val3 + val4 + val5 + val6 + val7 + val8
    //f('AllIncome').set('abc');
    f('MainIncome').set(totalNumC);

    // 2/11/26 - due to 99 skip code in SALARYD have to exclude it.
    //if (!f('SALARYD').any('12') && f('SALARYD').toBoolean()){
